import math


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    def better(i, j, i2, j2):
        return (prefix[j] - prefix[i]) * (j2 - i2) > (prefix[j2] - prefix[i2]) * (j - i)

    def cross(i, j, t):
        return (j - i) * (prefix[t] - prefix[j]) - (t - j) * (prefix[j] - prefix[i])

    hull = []
    best_i, best_j = 0, k

    for j in range(k, n + 1):
        idx = j - k
        while len(hull) >= 2 and cross(hull[-2], hull[-1], idx) <= 0:
            hull.pop()
        hull.append(idx)

        lo, hi = 0, len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            i1 = hull[mid]
            i2 = hull[mid + 1]
            left = (prefix[j] - prefix[i1]) * (j - i2)
            right = (prefix[j] - prefix[i2]) * (j - i1)
            if left < right:
                lo = mid + 1
            else:
                hi = mid
        i = hull[lo]
        if better(i, j, best_i, best_j):
            best_i, best_j = i, j

    num = prefix[best_j] - prefix[best_i]
    den = best_j - best_i
    g = math.gcd(num, den)
    return [num // g, den // g]
